using Godot;
using System;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class FluidSolverOperations
{
    private static Settings Collide(Variant callback,Vector3 from,Vector3 to,double radius,Vector3 velocity)=>GD.Load<GDScript>("res://scripts/actors/physics/fluid/fluid_solver.gd").Call("_invoke_collision",callback,from,to,radius,velocity).AsGodotDictionary();
    private static void Commit(Settings state,Vector3[] points,Vector3[] velocities,float[] foam,float[] density){state["points"]=points;state["velocities"]=velocities;state["fluid_foam"]=foam;state["fluid_density"]=density;}
    private static Vector3 Contact(Settings values,Settings state,GArray contacts,Settings result,Vector3 velocity,Vector3 original,float mass,int particle,ref float foam,double tick)
    {
        foam*=(float)Math.Exp(-tick/Math.Max(.05,values["fluid_foam_duration"].AsDouble()));foreach(var value in Get(result,"hits",new GArray()).AsGodotArray()){var hit=value.AsGodotDictionary();var normal=hit["normal"].AsVector3();var surface=Get(hit,"velocity",Vector3.Zero).AsVector3();var relative=velocity-surface;float impact=Math.Max(0,-relative.Dot(normal));if(impact>0)relative+=normal*impact*(1+values["fluid_restitution"].AsSingle());var tangent=relative-normal*relative.Dot(normal);relative-=tangent*(float)Math.Clamp(values["fluid_boundary_friction"].AsDouble()*tick*40,0,1);velocity=relative+surface;foam=Math.Max(foam,Math.Clamp(impact/6,0,1));if(contacts.Count<64&&impact>.1)contacts.Add(new Settings{["position"]=result["position"],["normal"]=normal,["relative_velocity"]=original-surface,["intensity"]=impact*mass,["actor"]=Get(hit,"actor",""),["preset"]=values["fluid_preset"].AsInt32(),["temperature"]=values["fluid_temperature"],["particle"]=particle});}return velocity.LimitLength(values["fluid_max_speed"].AsSingle());
    }
    public void step(Settings state,Settings values,Vector3 gravity,Vector3 impulse,double dt,Variant collide,GodotObject? compute)
    {
        var points=state["points"].AsVector3Array();if(points.Length==0)return;if(compute!=null&&compute.Call("available").AsBool()){gpu_step(state,values,gravity,impulse,dt,collide,compute);return;}double spacing=values["spacing"].AsDouble(),h=spacing*2.05,volume=spacing*spacing*spacing;int n=points.Length;var velocities=state["velocities"].AsVector3Array();var masses=state["fluid_masses"].AsFloat32Array();var foam=state["fluid_foam"].AsFloat32Array();var densityValues=state["fluid_density"].AsFloat32Array();var ids=state["fluid_ids"].AsInt32Array();double speed=0;foreach(var velocity in velocities)speed=Math.Max(speed,velocity.Length());int substeps=Math.Clamp(Math.Max(values["substeps"].AsInt32(),(int)Math.Ceiling(speed*dt/(spacing*.45))),1,8);double tick=dt/substeps;float tickF=(float)tick;var contacts=new GArray();state["fluid_contacts"]=contacts;long checks=0;state["fluid_checks"]=0;
        for(int substep=0;substep<substeps;substep++)
        {
            var previous=(Vector3[])points.Clone();for(int i=0;i<n;i++){if(substep==0)velocities[i]+=impulse/Math.Max(.001f,masses[i]);velocities[i]=(velocities[i]+gravity*tickF).LimitLength(values["fluid_max_speed"].AsSingle());points[i]+=velocities[i]*tickF;}var near=FindNeighbors(points,h);checks+=near.Checks;int iterations=values["iterations"].AsInt32();for(int iteration=0;iteration<iterations;iteration++){var lambda=new float[n];for(int i=0;i<n;i++){double density=volume*kernel(0,h),denominator=values["fluid_compliance"].AsDouble()/(spacing*spacing);var sumGradient=Vector3.Zero;foreach(int j in near.Neighbors[i]){var delta=points[i]-points[j];density+=volume*kernel(delta.LengthSquared(),h);var g=gradient(delta,h)*(float)volume;sumGradient+=g;denominator+=g.LengthSquared();}densityValues[i]=(float)density;denominator+=sumGradient.LengthSquared();lambda[i]=(float)(-Math.Max(density-1,0)/Math.Max(.000001,denominator));}var corrections=new Vector3[n];for(int i=0;i<n;i++){var correction=Vector3.Zero;foreach(int j in near.Neighbors[i]){var delta=points[i]-points[j];double artificial=-.00005*Math.Pow(kernel(delta.LengthSquared(),h)/kernel(h*h*.09,h),4)*spacing*spacing;correction+=gradient(delta,h)*(float)((lambda[i]+lambda[j]+artificial)*volume);}corrections[i]=correction.LimitLength((float)(spacing*.25));}for(int i=0;i<n;i++)points[i]+=corrections[i];if(iteration+1<iterations){near=FindNeighbors(points,h);checks+=near.Checks;}}
            var projected=new Vector3[n];for(int i=0;i<n;i++)projected[i]=(points[i]-previous[i])/tickF;double viscosity=values["fluid_viscosity"].AsDouble();if(values["fluid_preset"].AsInt32()==4)viscosity*=Math.Exp(Math.Clamp((1100-values["fluid_temperature"].AsDouble())/1000,-2,2));for(int i=0;i<n;i++){var weighted=Vector3.Zero;var attraction=Vector3.Zero;double weight=0;foreach(int j in near.Neighbors[i]){var delta=points[j]-points[i];double w=volume*kernel(delta.LengthSquared(),h);weighted+=(projected[j]-projected[i])*(float)w;weight+=w;if(delta.LengthSquared()>spacing*spacing)attraction+=delta*(float)(w*values["fluid_cohesion"].AsDouble());attraction+=delta*(float)(w*values["fluid_tension"].AsDouble()*.2);}var velocity=projected[i]+weighted*(float)((1-Math.Exp(-viscosity*tick))/Math.Max(1,weight))+attraction*tickF;var result=Collide(collide,previous[i],points[i],spacing*.32,velocity);points[i]=result["position"].AsVector3();velocities[i]=Contact(values,state,contacts,result,velocity,projected[i],masses[i],ids[i],ref foam[i],tick);if(!points[i].IsFinite()||!velocities[i].IsFinite()){points[i]=previous[i];velocities[i]=Vector3.Zero;}}
        }
        Commit(state,points,velocities,foam,densityValues);state["fluid_checks"]=checks;
    }
    public void gpu_step(Settings state,Settings values,Vector3 gravity,Vector3 impulse,double dt,Variant collide,GodotObject compute)
    {
        var points=state["points"].AsVector3Array();var velocities=state["velocities"].AsVector3Array();var masses=state["fluid_masses"].AsFloat32Array();var foam=state["fluid_foam"].AsFloat32Array();var ids=state["fluid_ids"].AsInt32Array();double spacing=values["spacing"].AsDouble(),speed=0;for(int i=0;i<points.Length;i++){velocities[i]+=impulse/Math.Max(.001f,masses[i]);speed=Math.Max(speed,velocities[i].Length());}int substeps=Math.Clamp(Math.Max(values["substeps"].AsInt32(),(int)Math.Ceiling(speed*dt/(spacing*.45))),1,8);double tick=dt/substeps;var contacts=new GArray();state["fluid_contacts"]=contacts;state["fluid_checks"]=0;state["velocities"]=velocities;for(int substep=0;substep<substeps;substep++){var previous=(Vector3[])points.Clone();compute.Call("project",state,values,gravity,tick);points=state["points"].AsVector3Array();velocities=state["velocities"].AsVector3Array();for(int i=0;i<points.Length;i++){var original=velocities[i];var result=Collide(collide,previous[i],points[i],spacing*.32,original);points[i]=result["position"].AsVector3();velocities[i]=Contact(values,state,contacts,result,original,original,masses[i],ids[i],ref foam[i],tick);if(!points[i].IsFinite()||!velocities[i].IsFinite()){points[i]=previous[i];velocities[i]=Vector3.Zero;}}state["points"]=points;state["velocities"]=velocities;state["fluid_foam"]=foam;}
    }
}
